<?php
namespace App\Http\Controllers;
use App\Models\{Booking,TourDeparture};use Illuminate\Http\{Request,RedirectResponse};use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;
class BookingController{
 public function store(Request $request):RedirectResponse{$data=$request->validate([
  'tour_id'=>['nullable','exists:tours,id'],'tour_departure_id'=>['nullable','exists:tour_departures,id'],'pickup_point_id'=>['nullable','exists:pickup_points,id'],'type'=>['required',Rule::in(['contact','tour','private_tour','visa','cruise','invoice','callback'])],
  'first_name'=>['required','string','max:100'],'last_name'=>['required','string','max:100'],'phone'=>['required','string','max:50'],'email'=>['required','email','max:255'],'whatsapp'=>['nullable','string','max:50'],'date_of_birth'=>['nullable','date'],'age'=>['nullable','integer','min:0','max:120'],'address'=>['nullable','string','max:255'],'participant_count'=>['required','integer','min:1','max:100'],'comments'=>['nullable','string'],'special_requests'=>['nullable','string'],'mobility_information'=>['nullable','string'],'food_allergies'=>['nullable','string'],'meal_selection'=>['nullable','string','max:100'],'promo_code'=>['nullable','string','max:100'],'source'=>['nullable','string','max:100'],'passengers'=>['nullable','array','max:99'],
  'passengers.*.first_name'=>['required_with:passengers','string','max:100'],'passengers.*.last_name'=>['required_with:passengers','string','max:100'],'passengers.*.category'=>['required_with:passengers',Rule::in(['adult','child','infant','senior','accompanying_person','complimentary','driver','group_leader'])],'passengers.*.age'=>['nullable','integer','min:0','max:120'],'passengers.*.date_of_birth'=>['nullable','date'],'passengers.*.phone'=>['nullable','string','max:50'],'passengers.*.email'=>['nullable','email'],'passengers.*.pickup_point_id'=>['nullable','exists:pickup_points,id'],'passengers.*.meal_selection'=>['nullable','string','max:100'],'passengers.*.notes'=>['nullable','string']]);
  DB::transaction(function()use($data){$passengers=$data['passengers']??[];unset($data['passengers']);if(!empty($data['tour_departure_id'])){$departure=TourDeparture::open()->when(!empty($data['tour_id']),fn($q)=>$q->where('tour_id',$data['tour_id']))->lockForUpdate()->find($data['tour_departure_id']);if(!$departure||!$departure->is_bookable)throw ValidationException::withMessages(['tour_departure_id'=>'This departure is no longer available. Please choose another date.']);if($departure->available_seats<$data['participant_count'])throw ValidationException::withMessages(['participant_count'=>"Only {$departure->available_seats} seats are left on this departure."]);}$booking=Booking::create($data);$booking->passengers()->createMany($passengers);});
  return back()->with('message','Your request has been received. A DreamTour representative will contact you to confirm your booking.');}
}
